// CANONICAL ClickUp comment-op serializer (ADR-066 Block 2). KEEP serializeCommentOps IDENTICAL across 3 sites:
// cu-webhook-producer/Detect Mention, assemble-task-context/Build Output + Collect Replies. Edit all three together.
// n8n Code nodes share no module; a sub-workflow on the producer webhook hot path would add an exec row per
// comment + a synchronous failure surface to mention-detection, so we keep 3 inline copies of this pure fn
// (rationale: ADR-066 Block 2 / current.md). Rich ops (doc_mention/bookmark/link) carry empty/weak .text and are
// dropped by ClickUp's flat comment_text/text_content; rebuild from ops so the reference survives (2026-06-30 pptx drop).
function serializeCommentOps(ops, flat) {
  const arr = Array.isArray(ops) ? ops : [];
  const rich = function (op) { return op && (op.type === 'doc_mention' || op.type === 'bookmark' || op.bookmark || (op.attributes && (op.attributes.bookmark || op.attributes.link))); };
  if (!arr.some(rich)) return (flat || arr.map(function (op) { return (op && op.text) || ''; }).join(''));
  return arr.map(function (op) {
    if (!op) return '';
    if (op.type === 'doc_mention') {
      const d = op.doc_mention || {};
      const team = d.teamId || d.workspaceId || '';
      const view = d.viewId || '';
      const page = d.pageId || op.text || '';
      const url = (team && view && page) ? ('https://app.clickup.com/' + team + '/docs/' + view + '/' + page) : '';
      const title = d.pageTitle ? (' "' + d.pageTitle + '"') : '';
      const ref = url ? (url + ' (doc ' + view + ', strona ' + page + ')') : ('doc ' + (view || '?') + ', strona ' + (page || '?'));
      return '[dokument ClickUp' + title + ': ' + ref + ']';
    }
    const at = op.attributes || {};
    const bm = op.bookmark || at.bookmark;
    if (bm) { const u = (typeof bm === 'string') ? bm : (bm.url || bm.href || ''); return u ? ('[link: ' + u + ']') : (op.text || ''); }
    if (at.link) { const u = (typeof at.link === 'string') ? at.link : (at.link.url || at.link.href || ''); return op.text ? (op.text + ' (' + u + ')') : ('[link: ' + u + ']'); }
    return op.text || '';
  }).join('');
}
function truncateKeepingLinks(s, n) {
  s = s || '';
  if (s.length <= n) return s;
  let head = s.slice(0, n), cut = [], from = 0;
  for (;;) {
    let o = s.indexOf('[dokument ClickUp', from);
    const o2 = s.indexOf('[link:', from);
    if (o === -1 || (o2 !== -1 && o2 < o)) o = o2;
    if (o === -1) break;
    const c = s.indexOf(']', o);
    if (c === -1) break;
    const m = s.slice(o, c + 1);
    if (head.indexOf(m) === -1) cut.push(m);
    from = c + 1;
  }
  if (cut.length) head = head + ' … ' + cut.join(' ');
  return head;
}
let top = [];
try {
  const r = $('Fetch Task Comments').first().json;
  top = (r.comments || []).slice(0, 30).map(c => ({
    id: c.id,
    author: (c.user && (c.user.username || c.user.email)) || '',
    text: truncateKeepingLinks(serializeCommentOps(c.comment, c.comment_text), 600),
    date: c.date
  }));
} catch(e) {}

let repliesByParent = {};
try { repliesByParent = $('Collect Replies').first().json.replies_by_parent || {}; } catch(e) {}

const task_comments = [];
for (const c of top) {
  task_comments.push(c);
  const reps = (repliesByParent[c.id] || []).slice().sort((a, b) => Number(a.date || 0) - Number(b.date || 0));
  for (const rep of reps) {
    task_comments.push({ id: rep.id, author: '\u21b3 ' + rep.author, text: rep.text, date: rep.date, parent_id: c.id, is_reply: true });
  }
}

// ADR-054 Block 3b: open-ended search-as-bot discovery + the Layer B (Check Space Member)
// post-hoc membership filter are RETIRED. Open-ended related-context discovery now runs
// in-harness via the per-user-scoped ClickUp MCP (Block 3a), enforced by the credential, not
// by a post-hoc filter (ADR-054 R3). This sub-workflow now returns only the triggering task's
// own comments (U already has access). additional_context is intentionally empty; the
// {task_comments, additional_context, sources_used, sources_filtered_out} contract is kept.
return [{ json: { task_comments, additional_context: '', sources_used: [], sources_filtered_out: 0 } }];

let thread_ids = [];
try {
  const r = $('Fetch Task Comments').first().json;
  thread_ids = (r.comments || [])
    .slice(0, 30)
    .filter(c => Number(c.reply_count || 0) > 0)
    .map(c => String(c.id));
} catch(e) {}
return [{ json: { thread_ids } }];

